const MAX_CHARS = 1200;
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const source = items[i].binary.data.fileName;
  const raw = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8').replace(/\r\n/g, '\n');

  // front matter: --- key: value ---
  const fm = {};
  let body = raw;
  const m = raw.match(/^---\n([\s\S]*?)\n---\n/);
  if (m) {
    for (const line of m[1].split('\n')) {
      const [k, ...v] = line.split(':');
      if (k && v.length) fm[k.trim()] = v.join(':').trim();
    }
    body = raw.slice(m[0].length);
  }
  const title = fm.title ?? source;
  const language = fm.language ?? (/\.de\.md$/.test(source) ? 'de' : 'en');

  // one chunk per "## " section; the text before the first section is the intro
  const sections = body.split(/\n(?=## )/).map((s) => s.trim()).filter(Boolean);
  const chunks = [];
  for (const sec of sections) {
    const heading = sec.startsWith('## ') ? sec.split('\n')[0].slice(3).trim() : null;
    const text = sec.replace(/^#+ .*\n?/, '').trim() || sec;
    for (let start = 0; start < text.length; start += MAX_CHARS) {
      const part = text.slice(start, start + MAX_CHARS);
      chunks.push({
        text: title + (heading ? ' > ' + heading : '') + '\n' + part,
        metadata: { source, title, section: heading, language, chunk: chunks.length },
      });
    }
  }
  out.push({ json: { source, language, chunks }, pairedItem: { item: i } });
}
return out;

const file = $('Split Into Chunks').item.json;
const vectors = $json.data;
if (!Array.isArray(vectors) || vectors.length !== file.chunks.length) {
  throw new Error('Embedding count mismatch for ' + file.source + ': got ' + (vectors?.length ?? 0) + ', expected ' + file.chunks.length);
}
const rows = file.chunks.map((c, i) => ({
  text: c.text,
  metadata: c.metadata,
  embedding: '[' + vectors[i].embedding.join(',') + ']', // pgvector text format
}));
return { json: { source: file.source, rows, dimensions: vectors[0].embedding.length } };

const files = $('Attach Vectors').all().map((i) => i.json);
return [{ json: {
  files: files.length,
  chunks: $input.all().length,
  dimensions: files[0]?.dimensions,
  sources: files.map((f) => f.source + ' (' + f.rows.length + ')'),
} }];

